#!/usr/bin/env node
// typeship — MCP server. Generated by typeship — https://typeship.dev
// Zero-dependency stdio transport: newline-delimited JSON-RPC 2.0.
// Every API operation is exposed as a tool; auth comes from environment
// variables (set them in your MCP client's server config).

import { createInterface } from "node:readline";
import { TypeshipClient } from "./index";
import { OPS, buildArgs, missingRequired, type OpSpec } from "./ops";

const SERVER_NAME = "typeship-mcp";
const SERVER_VERSION = "1.0.0";
const PROTOCOL_VERSION = "2025-03-26";
const DEFAULT_BASE_URL = "https://typeship.dev/api/v1";
const AUTH_SCALARS = [{"option":"bearerToken","flag":"token","env":"TYPESHIP_TOKEN"}] as const;
const BASIC: { envUser: string; envPass: string } | null = null;

function makeClient(): TypeshipClient {
  const options: Record<string, unknown> = {};
  const baseUrl = process.env["TYPESHIP_BASE_URL"] ?? DEFAULT_BASE_URL ?? undefined;
  if (baseUrl === undefined) {
    process.stderr.write("No base URL: set TYPESHIP_BASE_URL in the MCP server env.\n");
    process.exit(1);
  }
  options.baseUrl = baseUrl;
  for (const a of AUTH_SCALARS) {
    const v = process.env[a.env];
    if (v !== undefined) options[a.option] = v;
  }
  if (BASIC) {
    const username = process.env[BASIC.envUser];
    const password = process.env[BASIC.envPass];
    if (username !== undefined && password !== undefined) options.basicAuth = { username, password };
  }
  return new TypeshipClient(options as never);
}

const client = makeClient();

interface JsonRpcRequest {
  jsonrpc: "2.0";
  id?: number | string | null;
  method: string;
  params?: Record<string, unknown>;
}

function send(message: Record<string, unknown>): void {
  process.stdout.write(JSON.stringify(message) + "\n");
}

function reply(id: number | string | null, result: unknown): void {
  send({ jsonrpc: "2.0", id, result });
}

function replyError(id: number | string | null, code: number, message: string): void {
  send({ jsonrpc: "2.0", id, error: { code, message } });
}

function toolDefinitions(): unknown[] {
  return OPS.map((op) => ({
    name: op.tool,
    description:
      (op.summary ? op.summary + " — " : "") + op.httpMethod + " " + op.path +
      (op.paginated ? " (paginated: returns one page plus hasMore)" : ""),
    inputSchema: op.inputSchema,
  }));
}

async function callTool(op: OpSpec, args: Record<string, unknown>): Promise<{ text: string; isError: boolean }> {
  const values: Record<string, unknown> = {};
  for (const p of op.params) {
    if (args[p.name] !== undefined) values[p.name] = args[p.name];
  }
  const missing = missingRequired(op, values).filter((name) => !(op.bodyStyle === "data" && name === "body" && args.body !== undefined));
  if (missing.length > 0) {
    return { text: "Missing required argument(s): " + missing.join(", "), isError: true };
  }
  const callArgs = buildArgs(op, values, op.bodyStyle === "data" ? args.body : undefined);
  const target = (client as unknown as Record<string, Record<string, (...a: unknown[]) => unknown>>)[op.resource]!;
  try {
    const result = await (target[op.method]!(...callArgs) as Promise<{ ok: boolean; data?: unknown; error?: unknown }>);
    if (result.ok) {
      if (op.paginated) {
        const page = result.data as { items: unknown[]; hasNextPage(): boolean };
        return { text: JSON.stringify({ items: page.items, hasMore: page.hasNextPage() }, null, 2), isError: false };
      }
      return { text: JSON.stringify(result.data ?? { ok: true }, null, 2), isError: false };
    }
    const e = result.error as { name?: string; message?: string; status?: number; body?: unknown };
    return {
      text: JSON.stringify({ error: e?.name ?? "Error", message: e?.message, status: e?.status, body: e?.body }, null, 2),
      isError: true,
    };
  } catch (e) {
    return { text: (e as Error).message ?? "Tool call failed", isError: true };
  }
}

async function handle(request: JsonRpcRequest): Promise<void> {
  const id = request.id ?? null;
  switch (request.method) {
    case "initialize":
      reply(id, {
        protocolVersion: typeof request.params?.protocolVersion === "string" ? request.params.protocolVersion : PROTOCOL_VERSION,
        capabilities: { tools: {} },
        serverInfo: { name: SERVER_NAME, version: SERVER_VERSION },
      });
      return;
    case "ping":
      reply(id, {});
      return;
    case "tools/list":
      reply(id, { tools: toolDefinitions() });
      return;
    case "tools/call": {
      const name = request.params?.name;
      const op = OPS.find((o) => o.tool === name);
      if (!op) {
        replyError(id, -32602, "Unknown tool: " + String(name));
        return;
      }
      const args = (request.params?.arguments ?? {}) as Record<string, unknown>;
      const { text, isError } = await callTool(op, args);
      reply(id, { content: [{ type: "text", text }], isError });
      return;
    }
    default:
      if (request.method.startsWith("notifications/")) return; // fire-and-forget
      if (request.id === undefined) return; // unknown notification
      replyError(id, -32601, "Method not found: " + request.method);
  }
}

const rl = createInterface({ input: process.stdin });
rl.on("line", (line) => {
  const trimmed = line.trim();
  if (trimmed === "") return;
  let request: JsonRpcRequest;
  try {
    request = JSON.parse(trimmed) as JsonRpcRequest;
  } catch {
    send({ jsonrpc: "2.0", id: null, error: { code: -32700, message: "Parse error" } });
    return;
  }
  void handle(request).catch((e) => {
    if (request.id !== undefined) replyError(request.id ?? null, -32603, (e as Error).message ?? "Internal error");
  });
});
rl.on("close", () => process.exit(0));
